class Solution:
    def hasSeat(self, rows: List[List[int]], target: int) -> bool:
        r, c = 0, len(rows[0]) - 1
        while r < len(rows) and c >= 0:
            if rows[r][c] == target:
                return True
            if rows[r][c] > target:
                c -= 1
            else:
                r += 1
        return False

