class Solution {
    public boolean hasSeat(int[][] rows, int target) {
        int r = 0, c = rows[0].length - 1;
        while (r < rows.length && c >= 0) {
            if (rows[r][c] == target) return true;
            if (rows[r][c] > target) c--; else r++;
        }
        return false;
    }
}

