code.python:
class Solution:
    def hasSeat(self, rows: List[List[int]], target: int) -> bool:
        m, n = len(rows), len(rows[0])
        lo, hi = 0, m * n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            v = rows[mid // n][mid % n]
            if v == target:
                return True
            if v < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return False

